import math, random


def sigmoid(z):
    return 1 / (1 + math.exp(-z))


def inisialisasi(n_masuk, n_tersembunyi, seed):
    rng = random.Random(seed)
    W1 = [[rng.uniform(-1, 1) for _ in range(n_masuk)] for _ in range(n_tersembunyi)]
    W2 = [rng.uniform(-1, 1) for _ in range(n_tersembunyi)]
    return {"W1": W1, "b1": [0.0] * n_tersembunyi, "W2": W2, "b2": 0.0}


def forward(x, p):
    h = [math.tanh(sum(w * xi for w, xi in zip(baris, x)) + b) for baris, b in zip(p["W1"], p["b1"])]
    y_topi = sigmoid(sum(w * hj for w, hj in zip(p["W2"], h)) + p["b2"])
    return h, y_topi


def loss(y_topi, y):
    y_topi = min(max(y_topi, 1e-7), 1 - 1e-7)
    return -(y * math.log(y_topi) + (1 - y) * math.log(1 - y_topi))


def backward(x, y, p):
    h, y_topi = forward(x, p)
    d2 = y_topi - y
    d1 = [d2 * w * (1 - hj ** 2) for w, hj in zip(p["W2"], h)]
    return {
        "W1": [[dj * xi for xi in x] for dj in d1],
        "b1": d1,
        "W2": [d2 * hj for hj in h],
        "b2": d2,
    }


def latih(X, Y, p, epoch, lr):
    riwayat = []
    for _ in range(epoch):
        total = 0.0
        for x, y in zip(X, Y):
            total += loss(forward(x, p)[1], y)
            g = backward(x, y, p)
            for j in range(len(p["W1"])):
                for i in range(len(x)):
                    p["W1"][j][i] -= lr * g["W1"][j][i]
                p["b1"][j] -= lr * g["b1"][j]
                p["W2"][j] -= lr * g["W2"][j]
            p["b2"] -= lr * g["b2"]
        riwayat.append(total / len(X))
    return riwayat


def prediksi(x, p):
    return 1 if forward(x, p)[1] >= 0.5 else 0


def akurasi(X, Y, p):
    benar = sum(1 for x, y in zip(X, Y) if prediksi(x, p) == y)
    return round(benar / len(X), 2)


p = inisialisasi(3, 4, seed=7)
riwayat = latih(X, Y, p, epoch=100, lr=0.5)
print("loss awal:", round(riwayat[0], 4), "loss akhir:", round(riwayat[-1], 4))
print("akurasi:", akurasi(X, Y, p))
print("siswa baru:", prediksi([0.74, 0.5, 0.6], p))

