import math


def neuron(x, w, b, aktivasi):
    z = sum(xi * wi for xi, wi in zip(x, w)) + b
    if aktivasi == "relu":
        return max(0.0, z)
    if aktivasi == "sigmoid":
        return 1 / (1 + math.exp(-z))
    if aktivasi == "tanh":
        return math.tanh(z)
    return z


def softmax(z):
    m = max(z)
    e = [math.exp(v - m) for v in z]
    total = sum(e)
    return [v / total for v in e]


print(neuron([1, 0], [2.0, -1.0], -2.0, "sigmoid"))
