def early_stopping(loss_val, sabar):
    terbaik = float("inf")
    epoch_terbaik = 0
    tunggu = 0
    for epoch, nilai in enumerate(loss_val):
        if nilai < terbaik:
            terbaik, epoch_terbaik, tunggu = nilai, epoch, 0
        else:
            tunggu += 1
            if tunggu >= sabar:
                return epoch, epoch_terbaik
    return len(loss_val) - 1, epoch_terbaik


