import random


def dropout(nilai, p, seed):
    rng = random.Random(seed)
    return [0.0 if rng.random() < p else v / (1 - p) for v in nilai]


def penalti_l2(bobot, lam):
    return lam * sum(w * w for w in bobot)


print(dropout([1.0, 2.0, 3.0, 4.0], 0.5, seed=0))
