def konvolusi(gambar, filt):
    k = len(filt)
    hasil = []
    for i in range(len(gambar) - k + 1):
        baris = []
        for j in range(len(gambar[0]) - k + 1):
            baris.append(sum(gambar[i + a][j + b] * filt[a][b] for a in range(k) for b in range(k)))
        hasil.append(baris)
    return hasil


