import math, random


class Linear:
    def __init__(self, n_masuk, n_keluar, seed=0):
        rng = random.Random(seed)
        batas = 1 / math.sqrt(n_masuk)
        self.bobot = [[rng.uniform(-batas, batas) for _ in range(n_masuk)] for _ in range(n_keluar)]
        self.bias = [0.0] * n_keluar

    def __call__(self, x):
        return [sum(w * xi for w, xi in zip(baris, x)) + b for baris, b in zip(self.bobot, self.bias)]

    def jumlah_parameter(self):
        return sum(len(baris) for baris in self.bobot) + len(self.bias)


lapis = Linear(3, 4)
print(lapis.jumlah_parameter())
